import{_ as i,o as a,c as t,a1 as l}from"./chunks/framework.B8F5P-uw.js";const o=JSON.parse('{"title":"前端部分（简要介绍）","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"概念学习/网页制作/前端部分.md","filePath":"概念学习/网页制作/前端部分.md"}'),h={name:"概念学习/网页制作/前端部分.md"};function n(e,s,p,k,r,d){return a(),t("div",null,[...s[0]||(s[0]=[l(`<h1 id="前端部分-简要介绍" tabindex="-1">前端部分（简要介绍） <a class="header-anchor" href="#前端部分-简要介绍" aria-label="Permalink to &quot;前端部分（简要介绍）&quot;">​</a></h1><p>进一步了解可以参考 <a href="../../%E7%90%86%E8%AE%BA%E5%AD%A6%E4%B9%A0/%E7%AE%80%E4%BB%8B" target="blank">理论学习</a> 中的<code>前端</code>部分</p><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>Front‑end，客户端</p><p>用户可以直接看到、交互的一切，所见即所得</p><h2 id="前端三大件-html、css、javascript" tabindex="-1">前端三大件：HTML、CSS、JavaScript <a class="header-anchor" href="#前端三大件-html、css、javascript" aria-label="Permalink to &quot;前端三大件：HTML、CSS、JavaScript&quot;">​</a></h2><h3 id="_1-html是网页的骨架" tabindex="-1">1. HTML是网页的骨架 <a class="header-anchor" href="#_1-html是网页的骨架" aria-label="Permalink to &quot;1. HTML是网页的骨架&quot;">​</a></h3><p><strong>HyperText Markup Language 超文本标记语言</strong></p><ul><li>作用：搭网页结构，定义页面上有什么东西：标题、段落、按钮、图片、表格、输入框。</li><li>只负责“有什么”，<strong>不管长什么样，不管动作</strong>。</li><li>示例：</li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;标题&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;一段文字&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;按钮&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="_2-css是网页的样式" tabindex="-1">2. CSS是网页的样式 <a class="header-anchor" href="#_2-css是网页的样式" aria-label="Permalink to &quot;2. CSS是网页的样式&quot;">​</a></h3><p><strong>Cascading Style Sheets 层叠样式表</strong></p><ul><li>作用：控制外观：颜色、字体大小、间距、背景、布局、圆角、动画、排版。</li><li>管理网页的外观和布局，而不是实现点击交互等逻辑。</li><li>示例：设置字体红色，容器宽度，居中，阴影。</li></ul><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">red</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">font-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><h3 id="_3-javascript-js-是网页的行为交互" tabindex="-1">3. JavaScript(JS)是网页的行为交互 <a class="header-anchor" href="#_3-javascript-js-是网页的行为交互" aria-label="Permalink to &quot;3. JavaScript(JS)是网页的行为交互&quot;">​</a></h3><ul><li>作用：实现动态逻辑、交互。点击按钮、弹窗、表单校验、数据计算、网络请求、修改页面内容。</li><li>HTML是结构，CSS是样子，<strong>JS负责“做事情”</strong>。</li><li>示例：点击按钮弹出提示；表格增加一行；向后端请求数据渲染列表。</li></ul><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">alert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;你好&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">button.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onclick</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;按钮被点击&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }</span></span></code></pre></div><blockquote><p>三者协作关系： HTML搭骨架 → CSS美化 → JS负责交互干活。 只有HTML+CSS的网页是静态页面，不能响应用户操作；加上JS才是动态网页。</p></blockquote>`,18)])])}const g=i(h,[["render",n]]);export{o as __pageData,g as default};
